package org.sleepwell.app;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.media.*;

/** Real nonblocking 16kHz foreground-only microphone adapter. Never instantiated by native fixtures. */
final class NoteAudio implements NoteRuntime.Capture {
    private final Context context;private final java.util.function.BooleanSupplier current;private AudioRecord input;private MicrophoneLease lease;private long consumed,latest=-1;private final AudioTimestamp timestamp=new AudioTimestamp();
    private NoteAudio(Context context,java.util.function.BooleanSupplier current){this.context=context;this.current=current;}
    static NoteAudio open(Context context,java.util.function.BooleanSupplier current)throws Exception{NoteAudio capture=new NoteAudio(context,current);try{capture.allocate();return capture;}catch(Exception failure){try{capture.close();}catch(Exception cleanup){failure.addSuppressed(cleanup);throw new NoteRuntime.OpenFailure(capture,failure);}throw failure;}}
    private void allocate()throws Exception{check();if(context.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)throw new SecurityException("Microphone permission denied");lease=MicrophoneLease.acquire("note-challenge");if(lease==null)throw new IllegalStateException("Microphone occupied");try{int minimum=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(minimum<=0||minimum>32000)throw new IllegalStateException("Unsupported microphone format");input=new AudioRecord.Builder().setAudioSource(MediaRecorder.AudioSource.VOICE_RECOGNITION).setAudioFormat(new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_16BIT).setSampleRate(16000).setChannelMask(AudioFormat.CHANNEL_IN_MONO).build()).setBufferSizeInBytes(Math.max(4096,minimum)).setPrivacySensitive(true).build();if(input.getState()!=AudioRecord.STATE_INITIALIZED||input.getSampleRate()!=16000)throw new IllegalStateException("Microphone unavailable");}catch(Exception failure){throw failure;}}
    private void check(){if(!current.getAsBoolean()||context.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)throw new SecurityException("Microphone admission lost");AudioManager manager=context.getSystemService(AudioManager.class);if(manager==null||manager.getMode()!=AudioManager.MODE_NORMAL||TrackingService.running)throw new IllegalStateException("Microphone occupied");}
    public void start(){check();input.startRecording();if(input.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING)throw new IllegalStateException("Microphone did not start");}
    public long captured(){return latest;}
    public int read(short[] samples){check();AudioRecordingConfiguration configuration=input.getActiveRecordingConfiguration();if(configuration!=null&&configuration.isClientSilenced())throw new IllegalStateException("Microphone silenced");int count=input.read(samples,0,samples.length,AudioRecord.READ_NON_BLOCKING);latest=-1;if(count>0){consumed+=count;if(input.getTimestamp(timestamp,AudioTimestamp.TIMEBASE_MONOTONIC)==AudioRecord.SUCCESS){long mono=timestamp.nanoTime+(consumed-1-timestamp.framePosition)*62500L;long age=System.nanoTime()-mono;if(age>=0&&age<=400_000_000L)latest=android.os.SystemClock.elapsedRealtime()-age/1000000L;}}return count;}
    public void close(){AudioRecord owned=input;if(owned!=null){try{if(owned.getRecordingState()==AudioRecord.RECORDSTATE_RECORDING)owned.stop();}catch(RuntimeException ignored){}owned.release();input=null;}if(lease!=null){lease.released();lease=null;}}
}
